BODY={
'compat':'''blockers=[d["name"] for d in p["dependencies"] if p["target"] not in d["supports"]]\n    return {"ready":not blockers,"blockers":blockers}''',
'costs':'''total=sum(x["cost"] for x in p["usage"]); allocated=sum(x["cost"] for x in p["usage"] if x.get("tags"))\n    return {"total_cost":total,"allocated_cost":allocated,"unallocated_cost":total-allocated,"coverage_percent":round(100*allocated/total,1)}''',
'dedup':'''latest={}\n    for x in p["files"]:\n        if x["id"] not in latest or x["version"]>latest[x["id"]]["version"]: latest[x["id"]]=x\n    return {"latest":[latest[k] for k in sorted(latest)]}''',
'window':'''rows=sorted(p["periods"],key=lambda x:x["index"]); out=[]\n    for i,x in enumerate(rows): out.append({"index":x["index"],"average":round(sum(y["value"] for y in rows[max(0,i-1):i+1])/len(rows[max(0,i-1):i+1]),1)})\n    return {"trailing_2":out}''',
'gateway':'''ok=[x for x in p["requests"] if x in p["allowed"]]; bad=[x for x in p["requests"] if x not in p["allowed"]]\n    return {"allowed":ok,"blocked":bad}''',
'tags':'''out=[]\n    for x in p["assets"]: out.append({"name":x["name"],"tags":["contains_pii"] if "email" in x["columns"] else ["internal"]})\n    return {"assets":out}''',
'search':'''terms=set(p["query"].lower().split()); scored=[]\n    for d in p["documents"]:\n        score=len(terms & set(d["text"].lower().split()))\n        if score: scored.append((-score,d["id"]))\n    return {"ranking":[x[1] for x in sorted(scored)]}''',
'context':'''out=[]\n    for a in p["assets"]: out.append({"name":a["name"],"score":round(100*sum(bool(a["metadata"].get(k)) for k in p["required"])/len(p["required"]),1)})\n    return {"scores":out}''',
'variant':'''return {"columns":{field:[r["payload"].get(field) for r in p["records"]] for field in p["fields"]}}''',
'native':'''fallback=[x for x in p["operations"] if x not in p["native_supported"]]\n    return {"native":len(p["operations"])-len(fallback),"fallback":len(fallback),"fallback_operations":fallback}''',
'cdc':'''state=dict(p["initial"]); order=[]\n    for e in sorted(p["events"],key=lambda x:x["sequence"]): state.update(e["changes"]); order.append(e["sequence"])\n    return {"current":state,"applied_sequence":order}''',
'files':'''valid=[]; invalid=[]\n    for x in p["files"]:\n        good=(x["mode"]=="MANAGED" and x["uri"].startswith("/Volumes/")) or (x["mode"]=="EXTERNAL" and "://" in x["uri"])\n        (valid if good else invalid).append(x["name"])\n    return {"valid":valid,"invalid":invalid}''',
'libraries':'''good=[]; bad=[]\n    for x in p["libraries"]: (good if p["target_python"] in x["python"] else bad).append(x["name"])\n    return {"compatible":good,"incompatible":bad}''',
'capacity':'''return {"alerts":[x for x in p["events"] if x["utilization"]>=p["threshold"]]}''',
'gmail':'''latest={}\n    for x in p["messages"]:\n        if x["day"]>=p["cursor_day"] and (x["id"] not in latest or x["day"]>latest[x["id"]]): latest[x["id"]]=x["day"]\n    return {"ingested":sorted(latest),"new_cursor_day":max(latest.values(),default=p["cursor_day"])}''',
'workiva':'''latest={}\n    for x in p["activities"]:\n        if x["id"] not in latest or x["updated"]>latest[x["id"]]["updated"]: latest[x["id"]]=x\n    return {"latest":[latest[k] for k in sorted(latest)]}''',
'iceberg':'''required=set(p["required"]); good=[]; bad=[]\n    for x in p["clients"]: (good if required<=set(x["features"]) else bad).append(x["name"])\n    return {"compatible":good,"incompatible":bad}'''}

for slug,title,concept,kind,payload,expected in PROJECTS:
    base=ROOT/slug
    for name in ('src','data','tests','docs'): (base/name).mkdir(parents=True,exist_ok=True)
